666:                 #[cfg(all(feature = "rt-multi-thread", not(tokio_wasi)))]
667:                 Kind::MultiThread => false,
668:             },
669:             enable_io: self.enable_io,
670:             enable_time: self.enable_time,
671:             start_paused: self.start_paused,
672:             nevents: self.nevents,
673:         }
674:     }
675: 
