687:     /// let rt = runtime::Builder::new_multi_thread()
688:     ///     .thread_keep_alive(Duration::from_millis(100))
689:     ///     .build();
690:     /// # }
691:     /// ```
692:     pub fn thread_keep_alive(&mut self, duration: Duration) -> &mut Self {
693:         self.keep_alive = Some(duration);
694:         self
695:     }
